#[doc = "The bivectors of rigid motions (the Lie algebra of motors): the rotation `e12` and the translations `e1i, e2i`."]
///
/// Blades, in coefficient order: `[e12, e1i, e2i]`.
///
/// `S` lists the open slots: `Twist` (that is, `Twist<()>`) is a value, `Twist<(A,)>` a
/// linear map from `A`, `Twist<(A, B)>` a bilinear map. `T` is the coefficient type. `O` is
/// the orientation of the output, extrinsic by default (ADR-051).
#[repr(C)]
pub struct Twist<S: gx::Slots = (), T: gx::Coef = f64, O: gx::Orientation = gx::Extrinsic> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 3],
    o: core::marker::PhantomData<O>,
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> Clone for Twist<S, T, O> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> Copy for Twist<S, T, O> {}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> PartialEq for Twist<S, T, O> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation> core::fmt::Debug for Twist<S, T, O> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct(if O::SIGN < 0 { "intrinsic Twist" } else { "Twist" });
        for (b, c) in <Twist as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

// SAFETY: `Arr<X>` is `[X; 3]`, the layout `gx::FlatKind` promises.
unsafe impl<O: gx::Orientation> gx::FlatKind for Twist<(), f64, O> {}

impl<O: gx::Orientation> gx::Kind for Twist<(), f64, O> {
    const N: usize = 3;
    const NAME: &'static str = "Twist";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e12", "e1i", "e2i"];
    type Arr<X: gx::Elem> = [X; 3];
    type Mv<S: gx::Slots, T: gx::Coef> = Twist<S, T, O>;
    type Scalar = Scalar;
    type Orientation = O;
    const DEFAULT_INTRINSIC: bool = false;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 3] {
        [f(0), f(1), f(2)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 3], mut f: impl FnMut(&X) -> Y) -> [Y; 3] {
        [f(&a[0]), f(&a[1]), f(&a[2])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 3],
        b: &[Y; 3],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 3] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2])]
    }
}

