impl<T: gx::Real, O: gx::Orientation> Bivector<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t2 = x[2] * x[4];
        let t4 = (-x[5]).mul_add(x[5], t0);
        let t5 = x[1].mul_add(x[3], t2);
        let t7 = (-t5).mul_add(T::from_i64(2), t4);
        t7
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (54 mul, 28 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Bivector<(), T, O> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[5] * x[5];
        let t2 = x[1] * x[3];
        let t3 = x[2] * x[4];
        let t4 = x[0] * x[5];
        let t5 = x[1] * x[4];
        let t6 = x[2] * x[3];
        let t9 = t0 * t3;
        let t10 = t0 * t1;
        let t12 = t4 * t6;
        let t14 = t5 * t5;
        let t16 = t6 * t6;
        let t18 = t1 * t3;
        let t19 = t1 * t1;
        let t20 = t0.mul_add(t0, t19);
        let t22 = t2.mul_add(t2, t14);
        let t23 = t1.mul_add(t2, t16);
        let t24 = t22 + t23;
        let t25 = t3.mul_add(t3, t18);
        let t26 = t0.mul_add(t2, t9);
        let t27 = t25 - t26;
        let t28 = t24 + t27;
        let t30 = (-t4).mul_add(t5, t12);
        let t31 = t30 * T::from_i64(8);
        let t32 = t10.mul_add(T::from_i64(2), t20);
        let t33 = t28.mul_add(T::from_i64(4), t31);
        let t34 = t32 + t33;
        let t35 = t34.recip();
        let t36 = t0 * t35;
        let t38 = (-t1).mul_add(t35, t36);
        let t39 = t4 * t35;
        let t40 = t5 * t35;
        let t41 = t6 * t35;
        let t42 = t41 - t40;
        let t44 = t42.mul_add(T::from_i64(2), t39);
        let t45 = t39 - t40;
        let t46 = t39 + t41;
        let t47 = t2 * t35;
        let t48 = t3 * t35;
        let t49 = t47 + t48;
        let t50 = t38 * T::from_ratio(1, 2);
        let t51 = t47 - t50;
        let t52 = t48 - t50;
        let t53 = x[0] * t0;
        let t55 = x[0] * t49;
        let t56 = x[5] * t44;
        let t58 = x[2] * t46;
        let t60 = x[2] * t52;
        let t61 = x[3] * t51;
        let t64 = x[4] * t52;
        let t66 = x[5] * t1;
        let t67 = t35 * t66;
        let t68 = x[5] * t49;
        let t69 = t35.mul_add(t53, t56);
        let t71 = t55.mul_add(T::from_i64(2), -t69);
        let t72 = x[1].mul_add(t51, t58);
        let t73 = t72 * T::from_i64(2);
        let t74 = (-x[1]).mul_add(t45, t60);
        let t75 = t74 * T::from_i64(2);
        let t76 = (-x[4]).mul_add(t45, t61);
        let t77 = t76 * T::from_i64(2);
        let t78 = x[3].mul_add(t46, t64);
        let t79 = t78 * T::from_i64(2);
        let t80 = x[0].mul_add(t44, t67);
        let t82 = t68.mul_add(T::from_i64(2), t80);
        Bivector::from_coeffs([t71, t73, t75, t77, t79, t82])
    }

    /// [`inverse`](Self::inverse), or `None` where `x` has no inverse to working precision:
    /// where `x ~x`, the Study number `N` the inverse divides by, is zero next to `x`
    /// (`|N| â¤ n Îµ âxâÂ²`, with `|N|Â²` and `âxâÂ²` the sums of the squared coefficients of `N`
    /// and `x`, and `n = 6` the number of `x`'s), or its norm `d = N conj(N)` is lost to
    /// cancellation (`|d| â¤ n Îµ |N|Â²`), in any lane; or where the inverse is not finite.
    #[inline]
    pub fn try_inverse(self) -> Option<Bivector<(), T, O>> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[5] * x[5];
        let t2 = x[1] * x[3];
        let t3 = x[2] * x[4];
        let t4 = x[0] * x[5];
        let t5 = x[1] * x[4];
        let t6 = x[2] * x[3];
        let t9 = x[3] * x[3];
        let t13 = t0 * t3;
        let t14 = t0 * t1;
        let t16 = t4 * t6;
        let t18 = t5 * t5;
        let t20 = t6 * t6;
        let t22 = t1 * t3;
        let t23 = t1 * t1;
        let t24 = t0 + t1;
        let t25 = x[1].mul_add(x[1], t24);
        let t26 = x[2].mul_add(x[2], t9);
        let t27 = x[4].mul_add(x[4], t26);
        let t28 = t25 + t27;
        let t29 = t0 - t1;
        let t30 = t2 + t3;
        let t32 = (-t30).mul_add(T::from_i64(2), t29);
        let t33 = t5 - t4;
        let t34 = t33 - t6;
        let t35 = t34 * T::from_i64(2);
        let t36 = t0.mul_add(t0, t23);
        let t38 = t2.mul_add(t2, t18);
        let t39 = t1.mul_add(t2, t20);
        let t40 = t38 + t39;
        let t41 = t3.mul_add(t3, t22);
        let t42 = t0.mul_add(t2, t13);
        let t43 = t41 - t42;
        let t44 = t40 + t43;
        let t46 = (-t4).mul_add(t5, t16);
        let t47 = t46 * T::from_i64(8);
        let t48 = t14.mul_add(T::from_i64(2), t36);
        let t49 = t44.mul_add(T::from_i64(4), t47);
        let t50 = t48 + t49;
        let (size, d) = (t28, t50);
        let parts = t32 * t32 + t35 * t35;
        let tol = T::from_i64(6) * T::epsilon();
        if T::all_lt(tol * size, parts.sqrt()) && T::all_lt(tol * parts, d.abs()) {
            Some(self.inverse()).filter(gx::Extensor::is_finite)
        } else {
            None
        }
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn unit(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p2 = x[2] * x[4];
        let p5 = x[1] * x[4];
        let p7 = (-x[5]).mul_add(x[5], p0);
        let p8 = x[1].mul_add(x[3], p2);
        let p10 = (-p8).mul_add(T::from_i64(2), p7);
        let p11 = (-x[0]).mul_add(x[5], p5);
        let p12 = (-x[2]).mul_add(x[3], p11);
        let p13 = p12 * T::from_i64(2);
        let [s0, s1] = gx::__private::study::rsqrt(-1, p10, p13);
        let t1 = x[5] * s1;
        let t2 = x[1] * s0;
        let t5 = x[2] * s0;
        let t7 = x[4] * s1;
        let t9 = x[4] * s0;
        let t11 = x[5] * s0;
        let t12 = x[0].mul_add(s0, t1);
        let t13 = (-x[2]).mul_add(s1, t2);
        let t14 = x[1].mul_add(s1, t5);
        let t15 = x[3].mul_add(s0, t7);
        let t16 = (-x[3]).mul_add(s1, t9);
        let t17 = (-x[0]).mul_add(s1, t11);
        gx::Unit::new_unchecked(Bivector::from_coeffs([t12, t13, t14, t15, t16, t17]))
    }

    /// The same, uncertified: `self` scaled so that `x ~x = 1`, as a plain value. [`unit`](Self::unit)
    /// returns it as a [`gx::Unit`], which the cheaper unit kernels take.
    #[inline(always)]
    pub fn normalized(self) -> Self {
        self.unit().into_inner()
    }

}

impl<T: gx::Real> Bivector<(), T, gx::Extrinsic> {
    /// The exponential, a unit versor: `exp(B) = C(BÂ²) + S(BÂ²) B` with `BÂ²` a Study number.
    #[inline]
    #[allow(unused_variables)]
    pub fn exp(self) -> gx::Unit<Even<(), T>> {
        T::vectorize(#[inline(always)] move || {
        let x = self.c;
        let p2 = x[2] * x[4];
        let p3 = x[5] * x[5];
        let p6 = x[2] * x[3];
        let p7 = (-x[0]).mul_add(x[0], p3);
        let p8 = x[1].mul_add(x[3], p2);
        let p10 = p8.mul_add(T::from_i64(2), p7);
        let p11 = x[0].mul_add(x[5], p6);
        let p12 = (-x[1]).mul_add(x[4], p11);
        let p13 = p12 * T::from_i64(2);
        let [c0, c1, s0, s1] = gx::__private::study::exp_coeffs(-1, p10, p13);
        let t1 = x[5] * s1;
        let t2 = x[1] * s0;
        let t5 = x[2] * s0;
        let t7 = x[4] * s1;
        let t9 = x[4] * s0;
        let t11 = x[5] * s0;
        let t12 = x[0].mul_add(s0, t1);
        let t13 = (-x[2]).mul_add(s1, t2);
        let t14 = x[1].mul_add(s1, t5);
        let t15 = x[3].mul_add(s0, t7);
        let t16 = (-x[3]).mul_add(s1, t9);
        let t17 = (-x[0]).mul_add(s1, t11);
        gx::Unit::new_unchecked(Even::from_coeffs([c0, t12, t13, t14, t15, t16, t17, c1]))
        })
    }

}

impl<T: gx::Coef, O: gx::Orientation> gx::__private::NewtonStep for Bivector<(), T, O> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[5] * x[5];
        let t2 = t0 - t1;
        let t3 = t2 - T::from_i64(3);
        let t4 = x[0] * x[5];
        let t5 = x[1] * x[4];
        let t6 = x[2] * x[3];
        let t7 = t4 + t6;
        let t9 = (-t5).mul_add(T::from_i64(2), t7);
        let t10 = t4 - t5;
        let t12 = t6.mul_add(T::from_i64(2), t10);
        let t13 = t6 - t5;
        let t15 = t13.mul_add(T::from_ratio(2, 3), t4);
        let t16 = x[1] * x[3];
        let t17 = x[2] * x[4];
        let t18 = t16 + t17;
        let t19 = t3 * T::from_ratio(1, 2);
        let t20 = t16 - t19;
        let t21 = t17 - t19;
        let t22 = x[0] * t0;
        let t25 = x[1] * t20;
        let t28 = x[2] * t21;
        let t30 = x[4] * t12;
        let t32 = x[4] * t21;
        let t34 = x[5] * t1;
        let t37 = x[5].mul_add(t15, x[0]);
        let t38 = t37 * T::from_ratio(3, 2);
        let t39 = x[0].mul_add(t18, t38);
        let t40 = (-t22).mul_add(T::from_ratio(1, 2), t39);
        let t41 = (-x[2]).mul_add(t9, t25);
        let t42 = x[1].mul_add(t12, t28);
        let t43 = x[3].mul_add(t20, t30);
        let t44 = (-x[3]).mul_add(t9, t32);
        let t45 = t34 * T::from_ratio(1, 2);
        let t46 = (-x[0]).mul_add(t15, x[5]);
        let t48 = x[5].mul_add(t18, t45);
        let t49 = t46.mul_add(T::from_ratio(3, 2), t48);
        Bivector::from_coeffs([t40, t41, t42, t43, t44, t49])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

