impl<T: gx::Real, O: gx::Orientation> Trivector<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[1];
        let t2 = x[3] * x[3];
        let t3 = x[2].mul_add(x[2], t2);
        let t5 = t0.mul_add(T::from_i64(2), t3);
        let t6 = -t5;
        t6
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (23 mul, 7 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Trivector<(), T, O> {
        let x = self.c;
        let t0 = x[0] * x[1];
        let t1 = x[2] * x[2];
        let t2 = x[3] * x[3];
        let t4 = t0 * t1;
        let t7 = t1 * t2;
        let t8 = t2 * t2;
        let t9 = t1.mul_add(t1, t8);
        let t11 = t0.mul_add(t0, t4);
        let t12 = t0.mul_add(t2, t11);
        let t14 = t7.mul_add(T::from_i64(2), t9);
        let t15 = t12.mul_add(T::from_i64(4), t14);
        let t16 = t15.recip();
        let t19 = t2 * t16;
        let t20 = t1.mul_add(t16, t19);
        let t21 = t20 * T::from_ratio(1, 2);
        let t22 = t0.mul_add(t16, t21);
        let t23 = x[0] * t22;
        let t24 = x[1] * t22;
        let t25 = x[2] * t22;
        let t26 = x[3] * t22;
        let t27 = t23 * T::from_i64(2);
        let t28 = t24 * T::from_i64(2);
        let t29 = t25 * T::from_i64(2);
        let t30 = t26 * T::from_i64(2);
        Trivector::from_coeffs([t27, t28, t29, t30])
    }

    /// [`inverse`](Self::inverse), or `None` where `x` has no inverse to working precision:
    /// where `x ~x`, the Study number `N` the inverse divides by, is zero next to `x`
    /// (`|N| â¤ n Îµ âxâÂ²`, with `|N|Â²` and `âxâÂ²` the sums of the squared coefficients of `N`
    /// and `x`, and `n = 4` the number of `x`'s), or its norm `d = N conj(N)` is lost to
    /// cancellation (`|d| â¤ n Îµ |N|Â²`), in any lane; or where the inverse is not finite.
    #[inline]
    pub fn try_inverse(self) -> Option<Trivector<(), T, O>> {
        let x = self.c;
        let t0 = x[2] * x[2];
        let t1 = x[3] * x[3];
        let t2 = x[0] * x[1];
        let t4 = x[1] * x[1];
        let t6 = t0 * t2;
        let t9 = t0 * t1;
        let t10 = t1 * t1;
        let t11 = t0 + t1;
        let t12 = x[0].mul_add(x[0], t4);
        let t13 = t11 + t12;
        let t15 = t2.mul_add(T::from_i64(2), t11);
        let t16 = -t15;
        let t17 = t0.mul_add(t0, t10);
        let t19 = t2.mul_add(t2, t6);
        let t20 = t1.mul_add(t2, t19);
        let t22 = t9.mul_add(T::from_i64(2), t17);
        let t23 = t20.mul_add(T::from_i64(4), t22);
        let (size, d) = (t13, t23);
        let parts = t16 * t16;
        let tol = T::from_i64(4) * T::epsilon();
        if T::all_lt(tol * size, parts.sqrt()) && T::all_lt(tol * parts, d.abs()) {
            Some(self.inverse()).filter(gx::Extensor::is_finite)
        } else {
            None
        }
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn unit(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[1];
        let p2 = x[3] * x[3];
        let p3 = x[2].mul_add(x[2], p2);
        let p5 = p0.mul_add(T::from_i64(2), p3);
        let p6 = -p5;
        let s0 = (p6).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Trivector::from_coeffs([t0, t1, t2, t3]))
    }

    /// The same, uncertified: `self` scaled so that `x ~x = 1`, as a plain value. [`unit`](Self::unit)
    /// returns it as a [`gx::Unit`], which the cheaper unit kernels take.
    #[inline(always)]
    pub fn normalized(self) -> Self {
        self.unit().into_inner()
    }

}

impl<T: gx::Coef, O: gx::Orientation> gx::__private::NewtonStep for Trivector<(), T, O> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t2 = x[3] * x[3];
        let t3 = x[2].mul_add(x[2], t2);
        let t4 = t3 * T::from_ratio(1, 2);
        let t5 = x[0].mul_add(x[1], t4);
        let t7 = t5.mul_add(T::from_ratio(2, 3), T::from_i64(1));
        let t8 = x[0] * t7;
        let t9 = x[1] * t7;
        let t10 = x[2] * t7;
        let t11 = x[3] * t7;
        let t12 = t8 * T::from_ratio(3, 2);
        let t13 = t9 * T::from_ratio(3, 2);
        let t14 = t10 * T::from_ratio(3, 2);
        let t15 = t11 * T::from_ratio(3, 2);
        Trivector::from_coeffs([t12, t13, t14, t15])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

