impl<T: gx::Real, O: gx::Orientation> Motor<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t2 = x[0].mul_add(x[0], t1);
        t2
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (12 mul, 3 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Motor<(), T, O> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t3 = t0 * t1;
        let t4 = t1 * t1;
        let t5 = t0.mul_add(t0, t4);
        let t7 = t3.mul_add(T::from_i64(2), t5);
        let t8 = t7.recip();
        let t10 = t1 * t8;
        let t11 = t0.mul_add(t8, t10);
        let t12 = x[0] * t11;
        let t13 = x[1] * t11;
        let t14 = x[2] * t11;
        let t15 = x[3] * t11;
        let t16 = -t13;
        let t17 = -t14;
        let t18 = -t15;
        Motor::from_coeffs([t12, t16, t17, t18])
    }

    /// [`inverse`](Self::inverse), or `None` where `x` has no inverse to working precision:
    /// where `x ~x`, the Study number `N` the inverse divides by, is zero next to `x`
    /// (`|N| â¤ n Îµ âxâÂ²`, with `|N|Â²` and `âxâÂ²` the sums of the squared coefficients of `N`
    /// and `x`, and `n = 4` the number of `x`'s), or its norm `d = N conj(N)` is lost to
    /// cancellation (`|d| â¤ n Îµ |N|Â²`), in any lane; or where the inverse is not finite.
    #[inline]
    pub fn try_inverse(self) -> Option<Motor<(), T, O>> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t3 = x[3] * x[3];
        let t5 = t0 * t1;
        let t6 = t1 * t1;
        let t7 = t0 + t1;
        let t8 = x[2].mul_add(x[2], t3);
        let t9 = t7 + t8;
        let t10 = t0.mul_add(t0, t6);
        let t12 = t5.mul_add(T::from_i64(2), t10);
        let (size, d) = (t9, t12);
        let parts = t7 * t7;
        let tol = T::from_i64(4) * T::epsilon();
        if T::all_lt(tol * size, parts.sqrt()) && T::all_lt(tol * parts, d.abs()) {
            Some(self.inverse()).filter(gx::Extensor::is_finite)
        } else {
            None
        }
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn unit(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p2 = x[0].mul_add(x[0], p1);
        let s0 = (p2).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Motor::from_coeffs([t0, t1, t2, t3]))
    }

    /// The same, uncertified: `self` scaled so that `x ~x = 1`, as a plain value. [`unit`](Self::unit)
    /// returns it as a [`gx::Unit`], which the cheaper unit kernels take.
    #[inline(always)]
    pub fn normalized(self) -> Self {
        self.unit().into_inner()
    }

}

impl<T: gx::Real> Motor<(), T, gx::Extrinsic> {
    /// Not callable: the logarithm is [`gx::Unit::log`], on a certified unit versor
    /// (`self.unit().log()`). This method only makes the compile error say so.
    #[doc(hidden)]
    #[inline(always)]
    pub fn log(self) -> Twist<(), T, gx::Extrinsic>
    where
        Self: gx::__private::LogNeedsUnit<Twist<(), T, gx::Extrinsic>>,
    {
        gx::__private::LogNeedsUnit::log(self)
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline(always)]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Motor::from_coeffs(c).unit()
    }

}

impl<T: gx::Coef, O: gx::Orientation> gx::__private::NewtonStep for Motor<(), T, O> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t2 = x[0].mul_add(x[0], t1);
        let t4 = (-t2).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t5 = x[0] * t4;
        let t6 = x[1] * t4;
        let t7 = x[2] * t4;
        let t8 = x[3] * t4;
        let t9 = t5 * T::from_ratio(3, 2);
        let t10 = t6 * T::from_ratio(3, 2);
        let t11 = t7 * T::from_ratio(3, 2);
        let t12 = t8 * T::from_ratio(3, 2);
        Motor::from_coeffs([t9, t10, t11, t12])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

impl<T: gx::Real> gx::Log for Motor<(), T, gx::Extrinsic> {
    type Output = Twist<(), T, gx::Extrinsic>;
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(unit: gx::Unit<Self>) -> Twist<(), T, gx::Extrinsic> {
        T::vectorize(#[inline(always)] move || {
        let x = unit.into_inner().c;
        let p0 = x[1] * x[1];
        let p1 = -p0;
        let [h0, h1] = gx::__private::study::log_coeffs_rotation((x[0], T::from_i64(0)), (p1, T::from_i64(0)));
        let t0 = x[1] * h0;
        let t1 = x[2] * h0;
        let t2 = x[3] * h0;
        Twist::from_coeffs([t0, t1, t2])
        })
    }
}

