        let t6 = x[0] * x[7];
        let t7 = x[1] * x[6];
        let t8 = x[2] * x[5];
        let t9 = x[3] * x[4];
        let t11 = x[3] * x[3];
        let t19 = t0 * t3;
        let t23 = t1 * t1;
        let t24 = t1 * t4;
        let t28 = t7 * t8;
        let t29 = t7 * t9;
        let t31 = t8 * t8;
        let t34 = t9 * t9;
        let t37 = t3 * t5;
        let t39 = t2 * t3;
        let t40 = t3 * t3;
        let t41 = t0 + t1;
        let t42 = t2 + t3;
        let t43 = x[2].mul_add(x[2], t11);
        let t44 = x[4].mul_add(x[4], t43);
        let t45 = x[5].mul_add(x[5], t41);
        let t46 = t42 + t45;
        let t47 = t44 + t46;
        let t48 = t41 - t42;
        let t49 = t4 + t5;
        let t51 = (-t49).mul_add(T::from_i64(2), t48);
