        let t53 = t7 + t9;
        let t54 = t52 - t53;
        let t55 = t54 * T::from_i64(2);
        let t56 = t0.mul_add(t0, t23);
        let t57 = t2.mul_add(t2, t40);
        let t58 = t56 + t57;
        let t59 = t0.mul_add(t1, t19);
        let t60 = t1.mul_add(t2, t59);
        let t61 = (-t0).mul_add(t2, t39);
