        let t11 = x[3] * x[3];
        let t19 = t0 * t3;
        let t23 = t1 * t1;
        let t24 = t1 * t4;
        let t28 = t7 * t8;
        let t29 = t7 * t9;
        let t31 = t8 * t8;
        let t34 = t9 * t9;
